245		}
246		if basis.WarrantyDays != 30 || !basis.PurchaseTime.Equal(t0) || !basis.WarrantyExpiry.Equal(t0.Add(30*day)) {
247			t.Fatalf("history basis = (%v, %d, %v), want original terms",
248				basis.PurchaseTime, basis.WarrantyDays, basis.WarrantyExpiry)
249		}
